const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "0. Detectar ganadores listos"
 * Tipo: Code (JavaScript, "Run Once for All Items")
 * Config: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = cfg.SUPABASE_URL;
const headers = {
  apikey: cfg.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${cfg.SUPABASE_SERVICE_ROLE_KEY}`,
};

const videos = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?variant_generation_status=eq.ready&select=id,client_id,filename,storage_path,duration_sec,status,best_score,performance_classification,variant_generation_attempts,uploaded_at&order=uploaded_at.asc`,
  headers,
  json: true,
});

return videos.map((video) => ({ json: video }));

const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "1. Reclamar ganador y preparar contexto"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Config: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, EDIT_SPEC_API_URL
 */
const rawVideo = $json;
const SUPABASE_URL = cfg.SUPABASE_URL;
const headers = {
  apikey: cfg.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${cfg.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

async function getRows(query) {
  return this.helpers.httpRequest({
    method: 'GET', url: `${SUPABASE_URL}/rest/v1/${query}`, headers, json: true,
  });
}

// Claim atomico: si otro poll ya lo tomo, PostgREST devuelve [] y este item
// termina sin generar ni persistir nada duplicado.
const claimed = await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${rawVideo.id}&variant_generation_status=eq.ready`,
  headers,
  body: {
    variant_generation_status: 'in_progress',
    variant_generation_started_at: new Date().toISOString(),
    variant_generation_error: null,
    variant_generation_attempts: (rawVideo.variant_generation_attempts || 0) + 1,
  },
  json: true,
});
if (!claimed.length) return [];

const [transcripts, analyses, assetRows, brandRows, scoreRows, editSpecRows, renderRows, promptRes] = await Promise.all([
  getRows.call(this, `transcripts?raw_video_id=eq.${rawVideo.id}&select=text_full,words,language&order=created_at.desc&limit=1`),
  getRows.call(this, `analyses?raw_video_id=eq.${rawVideo.id}&select=tema,categoria,hook_principal,hook_score,score_calidad,descripcion_objetivo,raw_llm_response&order=created_at.desc&limit=1`),
  getRows.call(this, `assets?raw_video_id=eq.${rawVideo.id}&select=titulos,captions_ig,captions_tiktok,hashtags,hooks_alternativos,recomendacion_edicion`),
  getRows.call(this, `brand_kit?client_id=eq.${rawVideo.client_id}&select=logo_url,primary_color,accent_color,handle_instagram,handle_tiktok,end_card_cta&limit=1`),
  getRows.call(this, `scores?raw_video_id=eq.${rawVideo.id}&select=id,score_rendimiento,classification,platform,window,components,computed_at&order=score_rendimiento.desc,computed_at.desc&limit=1`),
  getRows.call(this, `edit_specs?raw_video_id=eq.${rawVideo.id}&validation_status=eq.valid&select=id,spec_json,version&order=version.desc&limit=1`),
  getRows.call(this, `renders?raw_video_id=eq.${rawVideo.id}&select=id&order=created_at.desc`),
  this.helpers.httpRequest({ method: 'GET', url: `${cfg.EDIT_SPEC_API_URL}/prompts/variant-director-system`, json: true }),
]);

const transcript = transcripts[0];
const analysis = analyses[0];
const assets = assetRows[0];
const brandKit = brandRows[0];
const winningScore = scoreRows[0];
const parentEditSpec = editSpecRows[0];
if (!transcript?.words?.length || !analysis || !assets || !brandKit || !winningScore || !parentEditSpec) {
  throw new Error(`Contexto incompleto para Capa 9 en raw_video ${rawVideo.id}: se requieren transcript.words, analysis, assets, brand_kit, score y edit_spec valido.`);
}

let manualRequest = null;
if (rawVideo.status === 'variant_requested' && renderRows.length) {
  const ids = renderRows.map((r) => r.id).join(',');
  const actions = await getRows.call(this, `review_actions?render_id=in.(${ids})&decision=eq.variant_requested&select=variant_type,comment,decided_at&order=decided_at.desc&limit=1`);
  manualRequest = actions[0] || null;
}

const sourceVideoUrl = parentEditSpec.spec_json?.source_video?.url ||
  `${SUPABASE_URL}/storage/v1/object/public/raw/${rawVideo.client_id}/${rawVideo.storage_path}`;
const baseSpec = parentEditSpec.spec_json;
const today = new Date().toISOString().slice(0, 10);
const seed = parseInt(rawVideo.id.replace(/-/g, '').slice(0, 8), 16) % 100000;
const variantIds = [0, 1, 2].map((n) => `VID-${today}-${String(seed + n).padStart(5, '0')}`);

const userPrompt = [
  '## Ganador y evidencia',
  JSON.stringify({
    raw_video: { ...rawVideo, source_video_url: sourceVideoUrl },
    best_score: rawVideo.best_score,
    performance_classification: rawVideo.performance_classification,
    winning_score: winningScore,
    analysis,
    assets,
    manual_request: manualRequest,
  }),
  '',
  '## Transcripcion completa',
  JSON.stringify({ text_full: transcript.text_full, words: transcript.words, language: transcript.language }),
  '',
  '## Edit spec ganador de referencia',
  JSON.stringify(baseSpec),
  '',
  '## Datos fijos para las variantes Tipo B',
  JSON.stringify({
    video_ids_en_orden: variantIds,
    client_id: rawVideo.client_id,
    raw_video_id: rawVideo.id,
    source_video: { url: sourceVideoUrl, duration_sec: rawVideo.duration_sec },
    platform: baseSpec.platform,
    branding: baseSpec.branding,
    meta_version: parentEditSpec.version + 1,
  }),
].join('\n');

return [{ json: {
  raw_video: rawVideo,
  parent_edit_spec_id: parentEditSpec.id,
  next_edit_spec_version: parentEditSpec.version + 1,
  manual_request: manualRequest,
  system_prompt: promptRes.text,
  user_prompt: userPrompt,
} }];

const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "2. Llamar Variant Director"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Config: ANTHROPIC_API_KEY, ANTHROPIC_VERSION, VARIANT_DIRECTOR_MODEL
 */
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': cfg.ANTHROPIC_API_KEY,
    'anthropic-version': cfg.ANTHROPIC_VERSION || '2023-06-01',
    'content-type': 'application/json',
  },
  body: {
    model: cfg.VARIANT_DIRECTOR_MODEL || cfg.EDIT_DIRECTOR_MODEL,
    max_tokens: 12000,
    temperature: 0.4,
    system: $json.system_prompt,
    messages: [{ role: 'user', content: $json.user_prompt }],
  },
  json: true,
});

const rawText = (response.content || []).map((b) => b.text || '').join('');
const cleaned = rawText.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '');
let candidate;
try { candidate = JSON.parse(cleaned); } catch (err) {
  throw new Error(`Variant Director no devolvio JSON valido: ${err.message}`);
}
const variants = candidate?.variants;
if (!Array.isArray(variants)) throw new Error('Variant Director no devolvio variants[].');
const bCount = variants.filter((v) => v.variant_type === 'B').length;
const aCount = variants.filter((v) => v.variant_type === 'A').length;
const wrongOrder = variants.some((v, i) => v.variant_type === 'B' && variants.slice(0, i).some((x) => x.variant_type === 'A'));
if (bCount < 2 || bCount > 3 || aCount < 5 || aCount > 7 || wrongOrder) {
  throw new Error(`Lote invalido: se esperaban 2-3 Tipo B primero y 5-7 Tipo A; llegaron B=${bCount}, A=${aCount}, orden_invalido=${wrongOrder}.`);
}
for (const [i, variant] of variants.entries()) {
  if (!variant.idea || !variant.angulo || !variant.winner_mechanism) throw new Error(`Variante ${i} incompleta.`);
  if (variant.variant_type === 'A' && (!variant.hook || !variant.guion)) throw new Error(`Variante Tipo A ${i} no tiene hook/guion.`);
  if (variant.variant_type === 'B' && !variant.edit_spec) throw new Error(`Variante Tipo B ${i} no tiene edit_spec completo.`);
}

return [{ json: { ...$json, llm_raw_text: rawText, variant_batch: candidate } }];

const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "3. Validar y reparar Tipo B"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Maximo 3 intentos totales por edit_spec (inicial + 2 reparaciones).
 * Config: EDIT_SPEC_API_URL, ANTHROPIC_API_KEY, ANTHROPIC_VERSION,
 *      VARIANT_DIRECTOR_MODEL o EDIT_DIRECTOR_MODEL
 */
const API = cfg.EDIT_SPEC_API_URL;
const variants = $json.variant_batch.variants;
const repairAudit = [];

async function parseLlm(response) {
  const text = (response.content || []).map((b) => b.text || '').join('').trim()
    .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '');
  try { return { value: JSON.parse(text), parseError: null }; }
  catch (err) { return { value: null, parseError: err.message }; }
}

for (let index = 0; index < variants.length; index += 1) {
  const variant = variants[index];
  if (variant.variant_type !== 'B') continue;
  let candidate = variant.edit_spec;
  let validation = null;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    validation = candidate
      ? await this.helpers.httpRequest({ method: 'POST', url: `${API}/validate`, body: { edit_spec: candidate }, json: true })
      : { valid: false, errors: [{ path: '(root)', message: 'La reparacion no devolvio JSON valido.' }] };
    repairAudit.push({ variant_index: index, attempt, valid: validation.valid, errors: validation.errors || [] });
    if (validation.valid) {
      variant.edit_spec = validation.data;
      variant.repair_attempts = attempt - 1;
      break;
    }
    if (attempt === 3) {
      throw new Error(`Tipo B ${index} invalida tras 3 intentos: ${JSON.stringify(validation.errors)}`);
    }
    const repair = await this.helpers.httpRequest({
      method: 'POST', url: `${API}/repair-prompt`,
      body: { edit_spec: candidate, errors: validation.errors }, json: true,
    });
    const llm = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages',
      headers: {
        'x-api-key': cfg.ANTHROPIC_API_KEY,
        'anthropic-version': cfg.ANTHROPIC_VERSION || '2023-06-01',
        'content-type': 'application/json',
      },
      body: {
        model: cfg.VARIANT_DIRECTOR_MODEL || cfg.EDIT_DIRECTOR_MODEL,
        max_tokens: 6000, temperature: 0.2, system: repair.system,
        messages: [{ role: 'user', content: repair.user }],
      },
      json: true,
    });
    const parsed = await parseLlm(llm);
    candidate = parsed.value;
    if (parsed.parseError) validation = { valid: false, errors: [{ path: '(root)', message: parsed.parseError }] };
  }
}

return [{ json: { ...$json, variant_batch: { ...$json.variant_batch, variants }, repair_audit: repairAudit } }];

const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "4. Persistir variantes y finalizar"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Config: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, TELEGRAM_BOT_TOKEN,
 *      TELEGRAM_CHAT_ID
 */
const SUPABASE_URL = cfg.SUPABASE_URL;
const headers = {
  apikey: cfg.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${cfg.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};
const raw = $json.raw_video;
const variants = $json.variant_batch.variants;
const typeB = variants.filter((v) => v.variant_type === 'B');
const typeA = variants.filter((v) => v.variant_type === 'A');

// generation_key + upsert hace recuperable un fallo parcial: una reejecucion
// no duplica las filas que alcanzaron a guardarse.
for (let i = 0; i < typeB.length; i += 1) {
  const variant = typeB[i];
  const generationKey = `${raw.id}:capa9:B:${i}`;
  const version = $json.next_edit_spec_version + i;
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/edit_specs?on_conflict=generation_key`,
    headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=representation' },
    body: {
      raw_video_id: raw.id,
      parent_edit_spec_id: $json.parent_edit_spec_id,
      template_id: variant.edit_spec.template_id,
      spec_json: variant.edit_spec,
      schema_version: variant.edit_spec.schema_version,
      version,
      status: 'ready',
      validation_status: 'valid',
      validation_errors: null,
      repair_attempts: variant.repair_attempts || 0,
      variant_type_origen: variant.variant_type_origen || 're_corte_automatico',
      generation_key: generationKey,
    },
    json: true,
  });
}

for (let i = 0; i < typeA.length; i += 1) {
  const variant = typeA[i];
  const generationKey = `${raw.id}:capa9:A:${i}`;
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/scripts?on_conflict=generation_key`,
    headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=representation' },
    body: {
      client_id: raw.client_id,
      parent_video_id: raw.id,
      variant_type: 'A_requiere_grabacion',
      variant_type_origen: variant.variant_type_origen || 'nuevo_guion',
      idea: variant.idea,
      hook: variant.hook,
      guion: variant.guion,
      angulo: variant.angulo,
      status: 'pendiente_grabacion',
      generation_key: generationKey,
    },
    json: true,
  });
}

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${raw.id}&variant_generation_status=eq.in_progress`,
  headers,
  body: {
    variant_generation_status: 'variants_generated',
    variant_generation_completed_at: new Date().toISOString(),
    variant_generation_error: null,
  },
  json: true,
});

let chatId = cfg.TELEGRAM_CHAT_ID;
const clients = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/clients?id=eq.${raw.client_id}&select=telegram_chat_id`,
  headers,
  json: true,
});
if (clients[0]?.telegram_chat_id) chatId = clients[0].telegram_chat_id;
let telegramAlert = 'sent';
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${cfg.TELEGRAM_BOT_TOKEN}/sendMessage`,
    body: {
      chat_id: chatId,
      text: `Variantes generadas para ${raw.filename || raw.id}: ${typeB.length} Tipo B listas para render y ${typeA.length} Tipo A pendientes de grabacion.`,
    },
    json: true,
  });
} catch (err) {
  // La alerta no revierte un lote ya persistido. El resultado lo deja visible.
  telegramAlert = `failed: ${err.message}`;
}

return [{ json: {
  raw_video_id: raw.id,
  outcome: 'variants_generated',
  type_a_count: typeA.length,
  type_b_count: typeB.length,
  telegram_alert: telegramAlert,
} }];

const cfg = $('0. Config').first().json;
/**
 * Nodo n8n: "99. Marcar generacion fallida"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Recibe el error output de los nodos Code de Capa 9.
 */
const SUPABASE_URL = cfg.SUPABASE_URL;
const rawVideoId = $json.raw_video?.id || $json.raw_video_id || $json.id;
if (!rawVideoId) throw new Error(`No se pudo identificar raw_video al manejar el error: ${JSON.stringify($json)}`);
const message = String($json.error?.message || $json.error || $json.message || 'Error no especificado en Capa 9').slice(0, 2000);
const headers = {
  apikey: cfg.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${cfg.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${rawVideoId}`,
  headers,
  body: { variant_generation_status: 'failed', variant_generation_error: message },
  json: true,
});

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${cfg.TELEGRAM_BOT_TOKEN}/sendMessage`,
    body: { chat_id: cfg.TELEGRAM_CHAT_ID, text: `Fallo Capa 9 para ${rawVideoId}: ${message}` },
    json: true,
  });
} catch (_) { /* el estado de error en Supabase es la fuente de verdad */ }

return [{ json: { raw_video_id: rawVideoId, outcome: 'failed', error: message } }];
